use super::*;
use super::Register as R;
use super::Clock;

fn advance(clock: &mut Clock, cycles: usize) -> usize {
    (0..cycles)
        .filter(|_| clock.tick() == Irq::Timer.into())
        .count()
}

fn fast_timer() -> Clock {
    let mut clock = Clock::new();
    clock.write(R::Tac, 0b101);
    clock
}

#[test]
fn div_exposes_the_upper_byte() {
    let mut clock = Clock::new();

    advance(&mut clock, 255);
    assert_eq!(clock.read(R::Div), 0);

    advance(&mut clock, 1);
    assert_eq!(clock.read(R::Div), 1);
}

#[test]
fn selected_clock_controls_the_increment_period() {
    for (selection, period) in [
        (0b00, 1024),
        (0b01, 16),
        (0b10, 64),
        (0b11, 256),
    ] {
        let mut clock = Clock::new();
        clock.write(R::Tac, 0b100 | selection);

        advance(&mut clock, period - 1);
        assert_eq!(clock.read(R::Tima), 0);

        advance(&mut clock, 1);
        assert_eq!(clock.read(R::Tima), 1);
    }
}

#[test]
fn resetting_div_can_increment_tima() {
    let mut clock = fast_timer();

    advance(&mut clock, 8);
    clock.write(R::Div, 0xFF);

    assert_eq!(clock.div, 0);
    assert_eq!(clock.read(R::Tima), 1);
}

#[test]
fn overflow_reloads_after_four_tcycles() {
    let mut clock = fast_timer();
    clock.write(R::Tima, 0xFF);
    clock.write(R::Tma, 0x42);

    assert_eq!(advance(&mut clock, 16), 0);
    assert_eq!(clock.read(R::Tima), 0);

    assert_eq!(advance(&mut clock, 3), 0);
    assert_eq!(clock.read(R::Tima), 0);

    assert_eq!(clock.tick(), Irq::Timer.into());
    assert_eq!(clock.read(R::Tima), 0x42);
}

#[test]
fn tima_write_cancels_pending_reload() {
    let mut clock = fast_timer();
    clock.write(R::Tima, 0xFF);

    advance(&mut clock, 16);
    clock.write(R::Tima, 0x77);

    assert_eq!(advance(&mut clock, 4), 0);
    assert_eq!(clock.read(R::Tima), 0x77);
}

#[test]
fn writes_during_active_reload_follow_the_chosen_model() {
    let mut clock = fast_timer();
    clock.write(R::Tima, 0xFF);
    clock.write(R::Tma, 0x42);

    assert_eq!(advance(&mut clock, 20), 1);

    clock.write(R::Tima, 0x99);
    assert_eq!(clock.read(R::Tima), 0x42);

    clock.write(R::Tma, 0x66);
    assert_eq!(clock.read(R::Tima), 0x66);

    advance(&mut clock, 4);
    clock.write(R::Tima, 0x99);
    assert_eq!(clock.read(R::Tima), 0x99);
}
